head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common_digital.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/buttonSet.js");
scwin.vScrenID = "ULDSTF70030_N3.xml"; //화면ID
scwin.v_SaveKind = ""; //신규,수정 구분

scwin.vBzProcsNo = ""; //업무처리번호	
scwin.vIsuCd = ""; //발행기관코드	
scwin.vDisclsYn = ""; // 공시여부 
//var vIsurCd  = "";      			// 상장인코드
//var vIsurNm = "";    				// 상장인명

scwin.vListBzTpCd = "790"; //상장업무구분코드 (삭제시 필요) - 로그처리방지용
//Transaction 처리코드
scwin.TR_JOB;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

//2017-02-13 KBoY FileSizeLimit 30MB		
scwin.canUploadFile = function() {
    var maxFileSize = 1024 * 1024 * 30; //30MB		
    var mySize = inf_find.FileInfo('size');
    if (mySize < maxFileSize) {
        return true;
    } else {
        return false;
    }
};


/********************************************** 
 * 함수명 : fn_filedown(bzProcsNo, attachFileNo) 
 * Params : bzProcsNo:업무처리번호 , attachFileNo: 번호
 * 설명    : 파일 다운로드 (gubun = 311)
 ***********************************************/
scwin.fn_filedown = function(bzProcsNo, attachSeq) {
    location.href = "/filedownload.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_08 + "&BZ_PROCS_NO=" + bzProcsNo + "&ATTACH_SEQ=" + attachSeq + "&gubun=311";
};


/********************************************** 
 * 함수명 : fn_file_sync() 
 * 설명    :  첨부파일 리스트 불러오기 
 ***********************************************/
scwin.fn_file_sync = function() {
    var url = "/digital/DigitalListinvstg.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=DigitalFileList&inputMessageId=DIGITAL_FILE_OUT";
    url += "&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    dts_fileList.DataID = encodeURI(url);
    dts_fileList.Reset();
};



/********************************************** 
 * 함수명 : fn_CheckForm(kind)
 * Params : kind( N:신규, U:수정)
 * 설명    : Form Validation Check
 ***********************************************/
scwin.fn_CheckForm = function(kind) {
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    if ($c.stf.getObjectValue(cmb_DIGITAL_SECU_EXP_YN) == "") {
        $c.win.alert("[만기유무]를 입력하세요.");
        cmb_DIGITAL_SECU_EXP_YN.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_DIGITAL_SECU_EXP_YN) == "Y") {
        if (txb_EXP_DD.getValue() == "") {
            $c.win.alert("[만기일]을 입력하세요.");
            txb_EXP_DD.focus();
            return false;
        }
        if (txb_LSTTRD_DD.getValue() == "") {
            $c.win.alert("[최종거래일]을 입력하세요.");
            txb_LSTTRD_DD.focus();
            return false;
        }
    }
    if ($c.stf.getObjectValue(edt_CHG_LIST_DD) == "") {
        $c.win.alert("[변경상장일]을 입력하세요.");
        edt_CHG_LIST_DD.focus();
        return false;
    }
    if (vCurDate >= $c.stf.getObjectValue(edt_CHG_LIST_DD)) {
        $c.win.alert("[변경상장일]을 현재일이후로 입력하세요.");
        edt_CHG_LIST_DD.focus();
        return false;
    }
    if (!scwin.fn_compDate()) return false;
    return true;
};



/********************************************** 
 * 함수명 : fn_dupCheck()
 * 설명    : 종목 중복날짜 체크
 ***********************************************/
scwin.fn_dupCheck = function() {
    var chgDd = $c.stf.getObjectValue(edt_CHG_LIST_DD);
    var isNotDup = true;
    dts_DupChk.removeAll();
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral&outputMessageId=DIGITAL_CODE_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.digital.exp_chglist.select.list_check" + "&{P}param01=" + scwin.vIsuCd + "&{P}param02=" + chgDd;
    dts_DupChk.DataID = encodeURI(url);
    dts_DupChk.reset();
    if (dts_DupChk.getTotalRow() > 0) {
        // 같은 건이 아니라면
        if (scwin.vBzProcsNo != dts_DupChk.getCellData(1, "BZ_PROCS_NO")) {
            isNotDup = false;
            $c.win.alert("동일한 날짜에 변경상장 지정된 종목이 존재합니다.");
        }
    }
    return isNotDup;
};


/********************************************** 
 * 함수명 : fn_select_isur()
 * 설명    : 만기변경 내역 신규 조회
 ***********************************************/
scwin.fn_select_isur = function() {
    var url = "/digital/DigitalListinvstg.do?method=listDigitalExpChangeDetailNewRequest";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&SRCH_ISU_CD=" + scwin.vIsuCd;
    dts_Isu.DataID = encodeURI(url);
    dts_Isu.Reset();

    //vIsurCd= dts_Isu.NameValue(1,"ISUR_CD");
    //vIsurNm = dts_Isu.NameValue(1,"ISUR_NM");

};





/********************************************** 
 * 함수명 : fn_select_isur()
 * 설명    : 만기변경 내역 조회
 ***********************************************/
scwin.fn_select_isur_Detail = function() {
    var url = "/digital/DigitalListinvstg.do?method=listDigitalExpChangeDetailUpdateRequest";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&SRCH_ISU_CD=" + scwin.vIsuCd;
    url += "&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    dts_Isu.DataID = encodeURI(url);
    dts_Isu.Reset();

    //vIsurCd= dts_Isu.NameValue(1,"ISUR_CD");
    //vIsurNm = dts_Isu.NameValue(1,"ISUR_NM");

};





/********************************************** 
 * 함수명 : fn_save_exp_isur_new()
 * 설명    : 변경상장 > 만기변경 > 신규저장
 ***********************************************/
scwin.fn_save_exp_isur_new = function() {
    //if (fn_CheckForm(v_SaveKind) == false)
    //return;

    scwin.TR_JOB = 'I';
    if (scwin.fn_CheckForm(scwin.v_SaveKind) && scwin.fn_dupCheck()) {
        //Transaction 처리전 안내문구
        if (!$c.lcd.fn_isProcess(scwin.TR_JOB)) return;
        // 저장 처리
        var vScrenId = "SCREN_ID=" + scwin.vScrenID;
        var vScrenTpId = "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        var vSrvMethod = "&method=insertExpChange";
        scwin.vBzProcsNo = $c.stf.fn_getNewBzProcNo(dts_BzProcsNo); //업무처리번호 새로 지정

        trs_Save.Action = "/digital/DigitalListinvstg.do?" + vScrenId + vScrenTpId + vSrvMethod;
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pInput=dts_Isu,I:pFile=dts_fileList)";
        trs_Save.Parameters = "TRS_IDX=" + TR_JOB_INSERT + ",LIST_BZ_TP_CD=" + scwin.vListBzTpCd + ",BZ_PROCS_NO=" + scwin.vBzProcsNo + ",ISU_CD=" + scwin.vIsuCd + ",ISUR_CD=" + dts_Isu.getCellData(1, "ISUR_CD") + ",ACPT_NO=" + js_emp_no + ",LD_MKT_TP_CD=1" + ",TRANSTR_EMP_NO=" + js_emp_no;
        trs_Save.Post();
    }
};



/********************************************** 
 * 함수명 : fn_save_exp_isur_update()
 * 설명    : 만기변경 > 상세보기  > 수정
 ***********************************************/
scwin.fn_save_exp_isur_update = function() {
    scwin.TR_JOB = 'U';

    //if (fn_CheckForm(TR_JOB) == false)
    //	return;


    if (($c.cp.isModified(dts_Isu) == false) && ($c.cp.isModified(dts_fileList) == false)) {
        $c.win.alert("수정내역이 존재하지 않습니다.");
        return;
    }
    if (scwin.fn_CheckForm(scwin.v_SaveKind) && scwin.fn_dupCheck()) {
        //Transaction 처리전 안내문구
        if (!$c.lcd.fn_isProcess(scwin.TR_JOB)) return;
        var vScrenId = "SCREN_ID=" + scwin.vScrenID;
        var vScrenTpId = "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
        var vSrvMethod = "&method=updateExpChange";
        trs_Save.Action = "/digital/DigitalListinvstg.do?" + vScrenId + vScrenTpId + vSrvMethod;
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pInput=dts_Isu,I:pFile=dts_fileList)";
        trs_Save.Parameters = "TRS_IDX=" + TR_JOB_UPDATE + ",LIST_BZ_TP_CD=" + scwin.vListBzTpCd + ",BZ_PROCS_NO=" + scwin.vBzProcsNo + ",ISU_CD=" + scwin.vIsuCd + ",ISUR_CD=" + dts_Isu.getCellData(1, "ISUR_CD") + ",ACPT_NO=" + js_emp_no + ",LD_MKT_TP_CD=1" + ",TRANSTR_EMP_NO=" + js_emp_no;
        trs_Save.Post();
    }
};



/********************************************** 
 * 함수명 : fn_save_exp_isur_delete
 * 설명    : 변경상장 > 만기변경 > 삭제
 ***********************************************/
scwin.fn_save_exp_isur_delete = function() {
    if (scwin.vBzProcsNo == "") {
        $c.win.alert("삭제 정보(업무처리번호)가 없습니다.");
        return;
    }
    // 공시 체크
    if (!$c.lcd.fn_check_delete_discls(dts_BzProcsNo, scwin.vBzProcsNo)) return;
    scwin.TR_JOB = 'D';

    //Transaction 처리전 안내문구
    if (!$c.lcd.fn_isProcess(scwin.TR_JOB)) return;
    buttonSet.setDeleteStatus(); // buttonSet에 CRUD상태를 저장하여 이용하는 사례, TR의 응답event에서 사용.

    var vScrenId = "SCREN_ID=" + scwin.vScrenID;
    var vScrenTpId = "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
    var vSrvMethod = "&method=deleteExpChange";

    //상장업무구분코드 있는 경우에만 삭제 처리 함
    if (scwin.vListBzTpCd != "") {
        trs_Save.Action = "/digital/DigitalListinvstg.do?" + vScrenId + vScrenTpId + vSrvMethod;
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pInput=dts_Isu)";
        trs_Save.Parameters = "TRS_IDX=" + TR_JOB_DELETE + ",LIST_BZ_TP_CD=" + scwin.vListBzTpCd + ",BZ_PROCS_NO=" + scwin.vBzProcsNo + ",ISU_CD=" + scwin.vIsuCd + ",ISUR_CD=" + dts_Isu.getCellData(1, "ISUR_CD") + ",ACPT_NO=" + js_emp_no + ",LD_MKT_TP_CD=1" + ",TRANSTR_EMP_NO=" + js_emp_no;
        trs_Save.Post();
    }
};




/********************************************** 
 * 함수명 : fn_checkModifyDts()
 * 설명    : 안내문작성 시, 수정사항 체크
 ***********************************************/
scwin.fn_checkModifyDts = function() {
    var rtn = false;
    if ($c.cp.isModified(dts_Isu) == false) {
        rtn = true;
    } else {
        $c.win.alert("변경된 내용이 있습니다. [수정] 후 진행하세요.");
        rtn = false;
    }
    return rtn;
};


/********************************************** 
 * 함수명 : fn_dscl()
 * 설명    : 수량변경 > 발행 및 상장내역 > 안내문 작성
 ***********************************************/
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.fn_dscl = async function() {
    var OldGet = scwin.fn_GetPar;
    var OldSet = scwin.fn_SetPar;
    var cCtnt = "";
    if (scwin.fn_checkModifyDts() == false) {
        return;
    }
    scwin.fn_GetPar = function(arr, param_dts_isu, param_dts_mst, param_dts2) {
        arr[0] = "69565C";
        arr[1] = scwin.vBzProcsNo;
        arr[2] = dts_Isu.getCellData(1, "ISUR_CD");
        arr[3] = '1';
        //arr[4] = fn_getEtcChgDisclsCtnt(); //ctnt
        arr[5] = $c.stf.getObjectValue(txb_ISU_NM); //add  title

        var sfeDate = scwin.dateForm(txb_BF_EXP_DD.getValue());
        var seDate = scwin.dateForm(txb_EXP_DD.getValue());
        var sDate = scwin.dateForm($c.stf.getObjectValue(edt_CHG_LIST_DD));
        $c.stf.CopyDataSet(dts_Isu, param_dts_isu);
        $c.stf.CopyDataSet(dts_Isu, param_dts_mst);

        // 파라미터 ds 만 값 변경
        param_dts_isu.setCellData(param_dts_isu.getFocusedRowIndex(), "BF_EXP_DD", sfeDate); // 이전만기일
        param_dts_isu.setCellData(param_dts_isu.getFocusedRowIndex(), "EXP_DD", seDate); // 만기일
        param_dts_mst.setCellData(param_dts_isu.getFocusedRowIndex(), "BF_EXP_DD", sfeDate);
        param_dts_mst.setCellData(param_dts_isu.getFocusedRowIndex(), "EXP_DD", seDate);
        param_dts_isu.setCellData(param_dts_isu.getFocusedRowIndex(), "CHG_LIST_DD", sDate); // 변경상장일
        param_dts_mst.setCellData(param_dts_mst.getFocusedRowIndex(), "CHG_LIST_DD", sDate);
        return arr.length;
    };
    scwin.fn_SetPar = function(arr) {

    };
    var wth = 750;
    var hgt = 820;
    var pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
    await $c.frame.CreateDialogFrame("ULDSTF92024", "/listingcommon/ULDSTF92024.gfm", "변경상장 만기변경 안내문작성", pt.x, pt.y, wth, hgt, "window");
    scwin.fn_GetPar = OldGet;
    scwin.fn_SetPar = OldSet;

    //안내문팝업 후 '닫기'나 '안내문전송' 후에 Popup Close 및 Parent Refresh 함
    $c.frame.path("../").fn_list_exp_chglist_sync();
};


/********************************************** 
 * 함수명 : fn_getQtyChgDisclsCtnt()
 * 설명    : 안내문작성 서식 (수량변경)
 ***********************************************/
scwin.fn_getEtcChgDisclsCtnt = function() {
    var vCtnt = "";
    vCtnt = "[공시제목] 신종증권 변경상장";
    vCtnt += "\r\n\r\n";
    vCtnt += "[본문내용]";
    vCtnt += "\r\n\r\n";
    vCtnt += "◎ " + $c.stf.getObjectValue(txb_ISU_NM) + " 변경상장(만기변경)";
    vCtnt += "\r\n\r\n";
    vCtnt += "1. 종목명 : " + $c.stf.getObjectValue(txb_ISU_NM);
    vCtnt += "\r\n\r\n";
    vCtnt += "2. 만기유무 : 변경전 " + $c.stf.getObjectValue(txb_ISU_NM); + " → 변경후 " + $c.stf.getObjectValue(txb_ISU_NM);
    vCtnt += "\r\n\r\n";
    vCtnt += "3. 만기일 : 변경전 " + scwin.dateForm($c.stf.getObjectValue(edt_CHG_LIST_DD)) + " → 변경후 " + scwin.dateForm($c.stf.getObjectValue(edt_CHG_LIST_DD));
    vCtnt += "\r\n\r\n";
    vCtnt += "4. 변경상장일 : " + scwin.dateForm($c.stf.getObjectValue(edt_CHG_LIST_DD));
    vCtnt += "\r\n\r\n";
    vCtnt += "5. 기타 : 만기 변경에 따른 최종거래일 변경은 추후 관련 공시를 참조하시기 바랍니다.";
    return vCtnt;
};


/********************************************** 
 * 함수명 : dateForm()
 * 설명    : 년월일 포맷 맞춤 (안내문 작성에서 사용)
 ***********************************************/
scwin.dateForm = function(pStr) {
    var str = "";
    if (pStr == "") {
        str = "없음"; // "★★★★년" + "★★월" + "★★일";

    } else {
        str = pStr.substring(0, 4) + "년 " + pStr.substring(4, 6) + "월 " + pStr.substring(6, 8) + "일";
    }
    return str;
};


/********************************************** 
 * 함수명 : fn_parentRefresh()
 * 설명    : Parent 화면 Refresh()
 ***********************************************/
scwin.fn_parentRefresh = function() {
    //Parent 신청내역 화면 Refresh
    var parentWin = $c.frame.path("../");
    parentWin.fn_list_exp_chglist_sync();
};
scwin.fn_compDate = function() {
    var rslt = true;
    if (txb_EXP_DD.getValue() != "" && txb_LSTTRD_DD.getValue() != "") {
        var expDd = txb_EXP_DD.getValue();
        var lsttrdDd = txb_LSTTRD_DD.getValue();
        if (expDd.length == 8 && lsttrdDd.length == 8) {
            if (expDd <= lsttrdDd) {
                $c.win.alert("최종거래일은 만기일 이전일자로 입력해야합니다.");
                rslt = false;
            }
        }
    }
    return rslt;
};
scwin.btn_ExpIsuClose_onclick = async function() {
    //닫기(수량변경)
    await $c.frame.CloseFrame();
};
scwin.gform_onload = function() {
    //Form onload event
    //PanelToGroupBox(panel_Item);

    var parentWin = $c.frame.path("../");

    //Transaction 구분: 신규(N), 수정(U), 삭제(D)
    scwin.v_SaveKind = parentWin.vIsuChgKind;
    scwin.vIsuCd = parentWin.clickIsuCd; // 종목 코드
    scwin.vDisclsYn = parentWin.clickDisclsYn; // 공시여부 

    // 파일 첨부 dataset header

    //dts_fileList.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
    if (scwin.v_SaveKind == "N") {
        //신규일 경우
        //정보조회
        scwin.fn_select_isur();
    } else if (scwin.v_SaveKind == "U") {
        scwin.vBzProcsNo = parentWin.clickBzProcsNo;
        scwin.vIsuCd = parentWin.clickIsuCd;

        //상세 정보 조회		
        scwin.fn_select_isur_Detail();
    }

    /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
    buttonSet.setSaveInfo(btn_Save, fn_save_exp_isur_new); // 저장
    buttonSet.setUpdateInfo(btn_Update, fn_save_exp_isur_update); // 수정
    buttonSet.setDeleteInfo(btn_Delete, fn_save_exp_isur_delete); // 삭제
    buttonSet.setDsclInfo(btn_Dscl, fn_dscl); // 안내문작성

};
scwin.trs_Save_OnSuccess = async function() {
    //저장메세지, 부모화면 Refresh, 화면 닫기
    $c.lcd.fn_alertMsg('S');
    scwin.fn_parentRefresh();
    if (buttonSet.status == "D") {
        // 삭제처리의 응답인 경우
        await $c.frame.CloseFrame();
    } else {
        scwin.fn_select_isur_Detail();
    }
};
scwin.trs_Save_OnFail = function() {
    $c.lcd.fn_alertMsg('F');
    $c.stf.alert_error(trs_Save);
};
scwin.img_CHG_LIST_DD_onclick = function() {
    //만기변경  > 상세 >  변경상장일 달력 클릭
    popUpCalendar2(edt_CHG_LIST_DD);
};
scwin.dts_Isu_OnLoadCompleted = function(rowcount) {
    // 신규처리에 의한 조회인지,  수정에 의한 조회인지를 구별
    if (scwin.vBzProcsNo == "") {
        buttonSet.setInsertStatus();
    } else {
        $c.stf.setButtonSetWithDate(edt_CHG_LIST_DD, false);
        $c.stf.setButtonSetWithDate2(scwin.vDisclsYn);
    }
    // 첨부파일 조회
    scwin.fn_file_sync();
};
scwin.dts_Isu_OnLoadError = function() {
    $c.stf.alert_error(dts_Isu);
};
scwin.img_LSTTRD_DD_onclick = function() {
    popUpCalendar2(txb_LSTTRD_DD);
};
scwin.img_EXP_DD_onclick = function() {
    popUpCalendar2(txb_EXP_DD);
};
scwin.grd_fielList_OnDblClick = function(row, colid) {
    // 파일다운로드	
    if (row == 0) return;
    if (dts_fileList.getRowStatus(dts_fileList.getRowPosition()) == 0) {
        $c.dn.fn_filedown(scwin.vBzProcsNo, dts_fileList.getCellData(row, "ATTACH_SEQ"));
    }
};
scwin.btn_file1_onclick = function() {
    if (dts_fileList.getTotalRow() == 5) {
        $c.win.alert("더이상 추가하실 수 없습니다.");
        return;
    }
    dts_fileList.insertRow();
    inf_find.open();
    if (inf_find.getValue() != "") {
        if (!$c.lcd.checkBadExt(inf_find.getValue())) {
            $c.win.alert("해당파일은 첨부하실 수 없습니다.");
            $c.cp.removeRow(dts_fileList, dts_fileList.getRowPosition());
            inf_find.setValue("");
            return;
        }
        dts_fileList.setCellData(dts_fileList.getRowPosition(), "ATTACH_FILE_NM", inf_find.getValue());
        dts_fileList.setCellData(dts_fileList.getRowPosition(), "ATTACH_SEQ", "0");
        dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileUrl", inf_find.getValue());

        //file_name.value = inf_find.Value;

    } else {
        $c.cp.removeRow(dts_fileList, dts_fileList.getRowPosition());
    }
    if (!scwin.canUploadFile()) {
        $c.win.alert('30MB 이하의 파일만 첨부 가능합니다.');
        $c.cp.removeRow(dts_fileList, dts_fileList.getRowPosition());
        return;
    }
    inf_find.setValue("");
};
scwin.btn_FileDelete_onclick = function() {
    $c.cp.removeRow(dts_fileList, dts_fileList.getRowPosition());
};
scwin.inf_find_OnClick = function() {

};
scwin.cmb_DIGITAL_SECU_EXP_YN_OnSelChange = function() {
    if ($c.stf.getObjectValue(cmb_DIGITAL_SECU_EXP_YN) == "N") {
        txb_EXP_DD.setValue("");
        txb_EXP_DD.setReadOnly(true);
        img_EXP_DD.setDisabled(true);
        img_EXP_DD.src = "../img/icn_calendar_d.gif";
    } else {
        txb_EXP_DD.setReadOnly(false);
        img_EXP_DD.setDisabled(false);
        img_EXP_DD.src = "../img/icn_calendar.gif";
    }
};
